import { mkdir, readFile, writeFile } from "node:fs/promises";
import process from "node:process";

const input = process.argv[2];
const check = process.argv.includes("--check");
const output = "clients/typescript/openapi-client.ts";
const document = JSON.parse(await readFile(input, "utf8"));
const lines = [
  "// Generated by scripts/ci/generate-openapi-client.mjs; DO NOT EDIT.",
  'export type Problem = { type: string; title: string; status: number; detail?: string; instance?: string };',
  "export type RequestOptions = { headers?: Record<string, string>; body?: unknown };",
  "export class OpenRevenueClient {",
  "  constructor(private readonly baseUrl: string, private readonly request: typeof fetch = fetch) {}",
];

for (const [path, item] of Object.entries(document.paths)) {
  for (const method of ["get", "post", "put", "patch", "delete"]) {
    const operation = item[method];
    if (!operation) continue;
    const params = [...path.matchAll(/\{([^}]+)\}/g)].map((match) => `${match[1]}: string`);
    params.push("options: RequestOptions = {}");
    const expression = path.replaceAll(/\{([^}]+)\}/g, "${encodeURIComponent($1)}");
    lines.push(`  async ${operation.operationId}(${params.join(", ")}): Promise<unknown> {`);
    lines.push(`    const response = await this.request(\`\${this.baseUrl}${expression}\`, { method: "${method.toUpperCase()}", headers: options.headers, body: options.body === undefined ? undefined : JSON.stringify(options.body) });`);
    lines.push("    if (!response.ok) throw await response.json() as Problem;");
    lines.push('    return response.status === 204 ? undefined : response.json();');
    lines.push("  }");
  }
}
lines.push("}", "");
const generated = lines.join("\n");
if (check) {
  const committed = await readFile(output, "utf8").catch(() => "");
  if (committed !== generated) {
    console.error(`${output} is stale; run pnpm contracts:generate`);
    process.exit(1);
  }
  console.log(`${output} is reproducible`);
} else {
  await mkdir("clients/typescript", { recursive: true });
  await writeFile(output, generated);
  console.log(`generated ${output}`);
}
